<script setup>
import {computed} from 'vue';import {t} from '../i18n';import {reviewPattern} from '../../core/pattern-quality.mjs';
const props=defineProps({revision:{type:Object,required:true}});const report=computed(()=>reviewPattern(props.revision));
</script>
<template><details class="form-section" open><summary>{{t('qualityReview')}}</summary><p class="notice">{{t('qualityCounts',{colors:report.usedColors,stitches:report.full,limit:revision.provenance.effectiveColorLimit})}}</p><p class="field-help">{{t('qualityRegionHelp',{regions:report.smallRegions,isolated:report.isolated,changed:revision.provenance.cleanup?.changedCells??0})}}</p><p class="field-help">{{t('qualityNoDeletion')}}</p><details><summary>{{t('palette')}} · {{report.usedColors}}</summary><div class="table-wrap" style="max-height:320px" tabindex="0" :aria-label="t('palette')"><table><thead><tr><th>{{t('color')}}</th><th>{{t('stitches')}}</th><th>{{t('qualityReview')}}</th></tr></thead><tbody><tr v-for="row in report.byColor" :key="row.index"><td>{{row.color.symbol}} · {{row.color.brand}} {{row.color.code}}</td><td>{{row.full}}</td><td><span v-if="row.total>0&&row.total<=report.rareThreshold" class="badge warning">{{t('qualityRare')}}</span></td></tr></tbody></table></div></details><details v-if="report.regions.length"><summary>{{t('qualityCoordinates')}}</summary><p class="field-help">{{t('qualityFirstRegions')}}</p><div class="table-wrap"><table><thead><tr><th>{{t('color')}}</th><th>{{t('insertColumn')}}</th><th>{{t('insertRow')}}</th><th>{{t('stitches')}}</th></tr></thead><tbody><tr v-for="(region,index) in report.regions" :key="index"><td>{{revision.colors[region.color].symbol}}</td><td>{{region.x+1}}</td><td>{{region.y+1}}</td><td>{{region.size}}</td></tr></tbody></table></div></details></details></template>
